import { CommonModule, isPlatformBrowser } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  Inject,
  OnInit,
  PLATFORM_ID,
} from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { LucideAngularModule } from 'lucide-angular';
import { PaymentsService } from '../../core/services/payments.service';
import { TranslationService } from '../../core/services/translation.service';

@Component({
  selector: 'app-payment-failed',
  standalone: true,
  imports: [CommonModule, RouterLink, LucideAngularModule],
  templateUrl: './payment-failed.component.html',
  styleUrl: './payment-failed.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PaymentFailedComponent implements OnInit {
  paymentData: Record<string, unknown> | null = null;
  paramData: string | null = null;
  private readonly isBrowser: boolean;

  constructor(
    public payementservice: PaymentsService,
        public translationService: TranslationService,
    public routes: Router,
    private readonly route: ActivatedRoute,
    @Inject(PLATFORM_ID) platformId: object
  ) {
    this.isBrowser = isPlatformBrowser(platformId);
  }

  ngOnInit(): void {
    this.paramData = this.route.snapshot.queryParamMap.get('ispayament');

    if (!this.isBrowser) {
      return;
    }

    const tempData = localStorage.getItem('stripe-payment-user');
    if (tempData) {
      this.paymentData = JSON.parse(tempData);
    }

    this.submitPayment();
  }

  submitPayment(): void {
    if (!this.paymentData) {
      return;
    }

    this.paymentData['payment_gateway'] = 'Stripe';
    this.paymentData['payment_method'] = 'Card';
    this.paymentData['status'] = 'Failed';

    this.payementservice.savePaymentSuccess(this.paymentData).subscribe({
      next: (response) => {
        if (response.body?.code === 200 && this.isBrowser) {
          localStorage.removeItem('stripe-payment-user');
          setTimeout(() => {
            this.routes.navigate(['/']);
          }, 3000);
        }
      },
    });
  }
}
